// Flattens paginated HubSpot pages and groups deal amount by ISO week of close date
const allItems = $input.all();
const weekly = {};

function isoWeekKey(dateStr) {
  const d = new Date(dateStr);
  if (isNaN(d)) return 'unknown';
  const target = new Date(d.valueOf());
  const dayNr = (d.getDay() + 6) % 7;
  target.setDate(target.getDate() - dayNr + 3);
  const firstThursday = new Date(target.getFullYear(), 0, 4);
  const weekNr = 1 + Math.round(((target - firstThursday) / 86400000 - 3 + ((firstThursday.getDay() + 6) % 7)) / 7);
  return `${target.getFullYear()}-W${String(weekNr).padStart(2, '0')}`;
}

for (const item of allItems) {
  const results = item.json.results || [item.json];
  for (const deal of results) {
    const props = deal.properties || deal;
    const week = isoWeekKey(props.closedate);
    if (!weekly[week]) weekly[week] = { week, dealCount: 0, dealValue: 0, byStage: {} };
    weekly[week].dealCount += 1;
    weekly[week].dealValue += Number(props.amount) || 0;
    const stage = props.dealstage || 'unknown';
    weekly[week].byStage[stage] = (weekly[week].byStage[stage] || 0) + 1;
  }
}

return Object.values(weekly).map(w => ({ json: w }));

// GA4 returns rows with dimensionValues (date) and metricValues (sessions)
const body = $input.first().json;
const rows = body.rows || [];
const weekly = {};

function isoWeekKey(yyyymmdd) {
  const d = new Date(`${yyyymmdd.slice(0,4)}-${yyyymmdd.slice(4,6)}-${yyyymmdd.slice(6,8)}`);
  const target = new Date(d.valueOf());
  const dayNr = (d.getDay() + 6) % 7;
  target.setDate(target.getDate() - dayNr + 3);
  const firstThursday = new Date(target.getFullYear(), 0, 4);
  const weekNr = 1 + Math.round(((target - firstThursday) / 86400000 - 3 + ((firstThursday.getDay() + 6) % 7)) / 7);
  return `${target.getFullYear()}-W${String(weekNr).padStart(2, '0')}`;
}

for (const row of rows) {
  const dateStr = row.dimensionValues[0].value;
  const sessions = Number(row.metricValues[0].value) || 0;
  const week = isoWeekKey(dateStr);
  if (!weekly[week]) weekly[week] = { week, sessions: 0 };
  weekly[week].sessions += sessions;
}

return Object.values(weekly).map(w => ({ json: w }));

const items = $input.all();
const rows = items.map(i => i.json);
const latest = rows.sort((a, b) => a.week.localeCompare(b.week)).slice(-1)[0] || {};

const sheetRows = rows.map(r => ({
  json: {
    week: r.week,
    dealCount: r.dealCount ?? 0,
    dealValue: r.dealValue ?? 0,
    sessions: r.sessions ?? 0
  }
}));

const summaryText = `Weekly report for ${latest.week || 'this period'}\n\nDeals closed: ${latest.dealCount ?? 0}\nDeal value: $${(latest.dealValue ?? 0).toLocaleString()}\nWebsite sessions: ${latest.sessions ?? 0}`;

return sheetRows.map((row, idx) => idx === 0 ? { json: { ...row.json, summaryText } } : row);
